#!/bin/sh
echo -e "a"
echo -E x
echo -n
echo -s x
echo -en x
echo -- -n
exec -a name cmd
exec cmd
let x=1
source ./a
. ./a
read
read -r
read -p prompt x
read -s x
printf "%q
" a
printf -v v x
printf %s q
trap "" err debug RETURN sigterm Term
trap - EXIT
wait -n
wait
hash -d
jobs -x
unset -v x
ulimit -n 1
umask -S
type -t ls
cd -L /
cd -@ /
export -n x
readonly -f g
